import type { SessionState } from '../api/redmist/session-state';
import type { SessionStatePatch } from '../api/redmist/session-state-patch';
import type { CarPosition } from '../api/redmist/car-position';
import type { CarPositionPatch } from '../api/redmist/car-position-patch';
import { Flags } from '../api/redmist/flags';

// Red Mist V2 patches are "nullable-field" objects (generated by the server's
// PatchClassGenerator): every property mirrors the base model and null means
// "no change". Merging is therefore a shallow copy of all non-null fields.
// See RedMist.Timing.UI LiveTimingViewModel for the reference implementation.

/**
 * Merge a SessionStatePatch into a SessionState. `carPositions` is
 * intentionally excluded — car updates are applied through the car map so lap
 * accumulation and pruning stay in one place (see sessionStore).
 */
export function mergeSessionPatch(base: SessionState, patch: SessionStatePatch): SessionState {
  const out: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (key === 'carPositions') continue;
    if (value !== null && value !== undefined) out[key] = value;
  }
  return out as unknown as SessionState;
}

export function mergeCarPatch(base: CarPosition, patch: CarPositionPatch): CarPosition {
  const out: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (value !== null && value !== undefined) out[key] = value;
  }
  return out as unknown as CarPosition;
}

