    lastLapTime: '',
    lastLapCompleted: 0,
    pitStopCount: null,
    lastLapPitted: null,
    lapsLedOverall: null,
    lapsLedInClass: null,
    overallPosition: 0,
    classPosition: 0,
    overallStartingPosition: 0,
    overallPositionsGained: -999,
    inClassStartingPosition: 0,
    inClassPositionsGained: -999,
